let catX = 100;
let catY = 100;
let catVY = 0;
let catSpeed = 5;
let groundY = 370;
let isJumping = false;

function setup() {
  createCanvas(400, 400);
}

function draw() {
  background(240);

  // ねこの描画
  fill(255, 100, 100); // ピンクっぽい色
  noStroke();
  ellipse(catX, catY, 30, 40); // 体
  ellipse(catX + 10, catY - 10, 15, 20); // 耳
  rect(catX - 10, catY + 10, 20, 20); // お腹

  // 足の描画
  fill(255);
  rect(catX - 5, catY + 20, 10, 10); // 左足
  rect(catX + 10, catY + 20, 10, 10); // 右足

  // 地面
  fill(150);
  rect(0, groundY, 400, 0);

  // 重力
  catVY = catVY + 0.5;

  // 地面に落ちたら止める
  if (catY > groundY) {
    catY = groundY;
    catVY = -catSpeed;
    isJumping = false;
  }

  // 落下アニメーション
  catY = catY + catVY;
}
```

