let buttonX = 100;
let buttonY = 50;
let myButtonWidth = 150;
let myButtonHeight = 50;
let myButtonColor = color(0, 0, 255); // 初期色は青

function setup() {
  createCanvas(400, 400);
  textAlign(CENTER, CENTER);
  textSize(16);
}

function draw() {
  background(240);

  // ボタンを描画
  fill(myButtonColor);
  rect(buttonX, buttonY, myButtonWidth, myButtonHeight);
  fill(255); // 文字色を白にリセット
  text("色を変える", buttonX + myButtonWidth / 2, buttonY + myButtonHeight / 2);

  // ボタンの色を切り替える処理
  if (myButtonColor === color(255, 100, 100)) {
    myButtonColor = color(0, 100, 0); // 赤に
  } else if (myButtonColor === color(0, 100, 0)) {
    myButtonColor = color(100, 0, 0); // 茶色に
  } else {
    myButtonColor = color(0, 0, 255); // 青に戻す
  }
}
